-- 1. Lock down the defaults
REVOKE ALL ON DATABASE shop FROM PUBLIC;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;

-- 2. Owner and groups (no login)
CREATE ROLE shop_owner NOLOGIN;
CREATE ROLE shop_read  NOLOGIN;
CREATE ROLE shop_write NOLOGIN;
ALTER SCHEMA public OWNER TO shop_owner;

-- 3. Group privileges
GRANT CONNECT ON DATABASE shop TO shop_read, shop_write;
GRANT USAGE ON SCHEMA public TO shop_read, shop_write;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO shop_read;
GRANT INSERT, UPDATE ON ALL TABLES IN SCHEMA public TO shop_write;
GRANT shop_read TO shop_write;

-- 4. Future tables follow the same rule
ALTER DEFAULT PRIVILEGES FOR ROLE shop_owner IN SCHEMA public
  GRANT SELECT ON TABLES TO shop_read;
ALTER DEFAULT PRIVILEGES FOR ROLE shop_owner IN SCHEMA public
  GRANT INSERT, UPDATE ON TABLES TO shop_write;

-- 5. Column-level restriction for a sensitive table
REVOKE SELECT ON customers FROM shop_read;
GRANT SELECT (id, country, created_at) ON customers TO shop_read;

